/**
 * Cache-related TypeScript interfaces for Claude Code Log.
 *
 * These interfaces maintain exact JSON structure compatibility with the Python cache system
 * defined in python/claude_code_log/cache.py. Any modifications should ensure compatibility
 * with existing Python cache files.
 */

/**
 * Information about a cached JSONL file.
 *
 * Corresponds to CachedFileInfo in python/claude_code_log/cache.py
 */
export interface CachedFileInfo {
  /** Path to the original JSONL file */
  file_path: string;

  /** Modification time of the source file when cached */
  source_mtime: number;

  /** Modification time of the cache file when created */
  cached_mtime: number;

  /** Number of messages in the cached file */
  message_count: number;

  /** List of session IDs found in this file */
  session_ids: string[];
}

/**
 * Cached session-level information.
 *
 * Corresponds to SessionCacheData in python/claude_code_log/cache.py
 */
export interface SessionCacheData {
  /** Unique session identifier */
  session_id: string;

  /** Optional session summary (generated by Claude or from first message) */
  summary?: string;

  /** ISO timestamp of the first message in the session */
  first_timestamp: string;

  /** ISO timestamp of the last message in the session */
  last_timestamp: string;

  /** Total number of messages in the session */
  message_count: number;

  /** First user message content for preview purposes */
  first_user_message: string;

  /** Working directory from session messages (if available) */
  cwd?: string;

  /** Total input tokens consumed in this session */
  total_input_tokens: number;

  /** Total output tokens generated in this session */
  total_output_tokens: number;

  /** Total cache creation tokens used in this session */
  total_cache_creation_tokens: number;

  /** Total cache read tokens used in this session */
  total_cache_read_tokens: number;
}

/**
 * Project-level cache index structure for index.json.
 *
 * Corresponds to ProjectCache in python/claude_code_log/cache.py
 */
export interface ProjectCache {
  /** Version of the library that created this cache */
  version: string;

  /** ISO timestamp when the cache was first created */
  cache_created: string;

  /** ISO timestamp when the cache was last updated */
  last_updated: string;

  /** Path to the project directory containing JSONL files */
  project_path: string;

  /** File-level cache information keyed by filename */
  cached_files: Record<string, CachedFileInfo>;

  /** Total number of messages across all files in the project */
  total_message_count: number;

  /** Total input tokens consumed across all sessions */
  total_input_tokens: number;

  /** Total output tokens generated across all sessions */
  total_output_tokens: number;

  /** Total cache creation tokens used across all sessions */
  total_cache_creation_tokens: number;

  /** Total cache read tokens used across all sessions */
  total_cache_read_tokens: number;

  /** Session metadata keyed by session ID */
  sessions: Record<string, SessionCacheData>;

  /** List of working directories associated with this project */
  working_directories: string[];

  /** ISO timestamp of the earliest message across all sessions */
  earliest_timestamp: string;

  /** ISO timestamp of the latest message across all sessions */
  latest_timestamp: string;
}

/**
 * Cache statistics for reporting and diagnostics.
 *
 * Used by cache management operations to report current state.
 */
export interface CacheStats {
  /** Whether caching is enabled and functional */
  cache_enabled: boolean;

  /** Number of files currently cached */
  cached_files_count?: number;

  /** Total number of cached messages */
  total_cached_messages?: number;

  /** Total number of sessions in cache */
  total_sessions?: number;

  /** ISO timestamp when cache was created */
  cache_created?: string;

  /** ISO timestamp when cache was last updated */
  last_updated?: string;
}

/**
 * Cache manager configuration options.
 */
export interface CacheManagerConfig {
  /** Path to the project directory */
  project_path: string;

  /** Current library version for cache invalidation */
  library_version: string;

  /** Optional custom cache directory name (defaults to 'cache') */
  cache_dir_name?: string;
}

/**
 * Options for loading cached entries with filtering.
 */
export interface CacheLoadOptions {
  /** Optional start date for filtering (ISO string or natural language) */
  from_date?: string;

  /** Optional end date for filtering (ISO string or natural language) */
  to_date?: string;

  /** Whether to include entries without timestamps */
  include_no_timestamp?: boolean;
}

/**
 * Result of cache validation operations.
 */
export interface CacheValidationResult {
  /** Whether the cache is valid */
  is_valid: boolean;

  /** Reason for invalidity (if applicable) */
  reason?: string;

  /** Whether cache version is compatible */
  version_compatible: boolean;

  /** List of files that need to be recached */
  files_to_recache: string[];
}
